<script>
import Layout from "../../../layouts/main";
import appConfig from "@/app.config";

export default {
  page: {
    meta: [
      {
        name: "description",
        content: appConfig.description,
      },
    ],
  },
  components: {
    Layout,
  },
  data() {
    return {
      agents: [],
      accounts: [],
      purchaseOrder: {},
      agent: { search: null },
      selectedAccounts: null,
      levelThreeAccountId: null,
      filteredAccounts: [],
      branchItem: {
        isNew: 1,
        item: {},
        code: null,
        account: null,
        Adaccount: null,
      },
      addExpense: [],
      reference_no: null,
      purchase_order_types: [],
      purchase_type: {},
      fixed_assets: [],
      company_branches: [],
            user:{}

    };
  },
  methods: {
    selectedAccount(search) {
      this.http
        .post("level-three-chart-of-accounts-copy-1/accounts-setup/search", {
          search,
          type: "Expense",
          level: 3,
        })
        .then((res) => {
          if (res.status) {
            this.filteredAccounts = res.data;
          }
          this.search = "";
        });
    },
    showAccountLabel(one) {
      return this.$i18n.locale == "en"
        ? one.code + " - " + one.name_en
        : one.code + " - " + one.name;
    },
    editPo() {
      console.log("step 67 :", {
        addExpense: this.addExpense,
        reference_no: this.reference_no, 
          purchase_order_type:this.purchase_type,
      });

      this.http
        .post("purchases/edit-order", {
          expenses: this.addExpense,
          id: this.purchaseOrder?.id,
          reference_no: this.reference_no,
                    purchase_order_type:this.purchase_type,

        })
        .then((res) => {
          if (res.status) {
            this.$router.push("/payments_invoices");
          }
        });
    },
    deleteOption(index) {
      this.addExpense.splice(index, 1);
    },
    getPurchaseOrderTypes() {
      this.http.get("purchases/purchase-order-types").then((res) => {
        if (res.status) {
          this.purchase_order_types = res.data;
          this.purchase_type = this.purchase_order_types[0];
        }
      });
    },
    fixedAssetSearch(search) {
      this.http
        .post("fixed-assets/search", {
          search,
          page: 1,
          limit: 20,
        })
        .then((res) => {
          if (res.status) {
            this.fixed_assets = res.data;
          }
        });
    },

    showAssetLabel(one) {
      console.log("step 139 :", one);

      return this.$i18n.locale == "en" ? one.name_en : one.name;
    },
    getBranchSites(branch_id, index) {
      console.log(index);
      return new Promise((resolve) => {
        this.http
          .post("level-one-chart-of-accounts/get-branch-sites", { branch_id })
          .then((resp) => {
            console.log(resp.data);
            this.addExpense[index].branch_sites = resp.data;
            resolve();
          });
      });
    },
    getBranches() {
      this.http.get("branches").then((res) => {
        if (res.status) this.company_branches = res.data;
      });
    },
       getBranchSubSites (branch_site_id, index) {
      // this.addExpense[index].branch_sub_site_id = null;
      this.http.get('level-one-chart-of-accounts/branch-sub-sites/'+  branch_site_id ).then(resp => {
        this.addExpense[index].branch_sub_sites = resp.data;
      });
    },
  },
  computed: {
    filteredAgents() {
      return this.agents.filter((account) => {
        return account;
      });
    },
  },
  created() {
    this.getBranches();
    this.getPurchaseOrderTypes();

    this.http
      .post("purchases/get-order", { id: this.$route.params.id })
      .then((res) => {
        if (res.status) {
          console.log(res.data);
          this.purchaseOrder = res.data;
          this.purchase_type = this.purchaseOrder.purchase_order_type;
          this.reference_no = this.purchaseOrder.reference_no;
          const details = res.data?.purchase_order_details;
          
          for (let index = 0; index < details.length; index++) {
            if (this.purchase_type.code == "expenses")
              this.addExpense.push({
                search: {
                  name: details[index]?.level_three_chart_of_account.name,
                  name_en:
                    details[index]?.level_three_chart_of_account?.name_en,
                  code: details[index]?.level_three_chart_of_account?.code,
                },
                unit_price: details[index]?.unit_price,
                qty: details[index]?.qty,
              });
            else {
              details[index].fixed_asset.depreciable=details[index]?.fixed_asset?.fixed_asset_type?.depreciable 
              this.addExpense.push({
                ...details[index],
                initial_book_value: details[index]?.unit_price,
                qty: details[index]?.qty,
              });
              this.getBranchSites(details[index].branch_id,index).then(()=>{
                this.addExpense[index].branch_site_id=details[index]?.branch_sub_site?.branch_site_id
                this.getBranchSubSites(details[index]?.branch_sub_site?.branch_site_id,index)
                console.log("step 179 :",this.addExpense[index]);
              })
            }
          }
        }
      });
  },
  mounted() {
     this.user=JSON.parse(localStorage.currentUser) 
    console.log("user :",this.user);
  },
};
</script>

<template>
  <Layout>
    <div class="row">
