            <h4 class="m-0">{{ $t("payments.title") }}</h4>
          </router-link>
          <div class="mx-2">\</div>
          <div># {{ purchaseOrder?.id }}</div>
        </div>
      </div>
    </div>

    <div class="row">
      <div class="col-12">
        <div class="card">
          <form @submit.prevent="editPo()">
