                        <span class="fw-bold">
                          {{ $t("purchases.purchase_type") }}
                        </span>
                      </div>
                      <div
                        v-for="(type, index) in purchase_order_types"
                        :key="index"
                        class="form-check form-check-inline"
                      >
                        <input
                          class="form-check-input"
                          type="radio"
                          v-model="purchase_type"
                          @change="
                            addExpense = [{}];
                            addExpense = [{}];
                          "
                          id="t1"
                          :value="type"
                        />
                        <label class="form-check-label" for="t1">{{
                          $i18n.locale == "en" ? type.name_en : type.name
                        }}</label>
                      </div>
                    </div>
                  </div>
                  <div class="row mb-2">
                    <div class="col-10">
                      <label for="asset_id">{{
                        $t("purchases.chose_items")
                      }}</label>
                    </div>
                    <div class="col-2">
                      <button
                        type="button"
                        @click="addExpense.push({})"
                        class="btn"
                      >
                        <span
                          class="bx bxs-plus-circle fa-2x"
                          style="color: #2a3042 !important"
                        ></span>
                      </button>
                    </div>
                  </div>
                  <div v-if="purchase_type?.code == 'expenses'" class="mt-3">
                    <div v-for="(expense, index) in addExpense" :key="expense">
                      <div class="row mb-2">
                        <div class="col">
                          <AutoComplete
                            v-model="expense.search"
                            :suggestions="filteredAccounts"
                            @complete="selectedAccount($event.query)"
                            :optionLabel="showAccountLabel"
                            :completeOnFocus="true"
                            style="
                              color: #333 !important;
                              border-radius: 10px !important;
                            "
                          />
                        </div>
                        <div class="col d-flex">
                          <input
                            required
                            type="number"
                            style="margin-inline-end: 4px; display: inline"
                            v-model="expense.qty"
                            class="form-control"
                            :placeholder="$t('emps.qty')"
                          />
                          <input
                            required
                            type="number"
                            style="display: inline"
                            v-model="expense.unit_price"
                            class="form-control"
                            :placeholder="$t('emps.unit_price')"
                          />
                        </div>
                        <div class="col">
                          <button
                            class="btn btn-sm btn-danger"
                            @click="deleteOption(index)"
                            :disabled="addExpense.length == 1"
                          >
                            <i class="bx bx-trash"></i>
                          </button>
                        </div>
                      </div>
                    </div>
                  </div>
                  <div
                    v-else
                    class="my-2 row"
                    v-for="(asset_product, index) in addExpense"
                    :key="index"
                  >
                    <div class="col-6"></div>
                    <div class="col-6 mt-3">
                      <button
                        type="button"
                        :disabled="addExpense.length == 1"
                        @click="addExpense.splice(index, 1)"
                        class="btn btn-danger float-end"
                      >
                        <span
                          class="bx bxs-trash"
                          style="color: #fff !important"
                        ></span>
                      </button>
                    </div>
                    <div class="col-12 col-md-4">
                      <div class="form-group">
                        <label>{{ $t("fixed_assets.fixed_asset") }}</label>

                        <AutoComplete
                          v-model="asset_product.fixed_asset"
                          :suggestions="fixed_assets"
                          :complete-on-focus="true"
                          @complete="fixedAssetSearch($event.query)"
                          @item-select="
                            asset_product.fixed_asset_id =
                              asset_product.fixed_asset?.id
                          "
                          :optionLabel="showAssetLabel"
                          class="w-100"
                          :input-class="'form-control w-100'"
                          required
                        />
                      </div>
                    </div>
                    <div class="col-12 col-md-4">
                      <label for="asset_id">{{
                        $t("fixed_assets.serial_no")
                      }}</label>
                      <input
                        type="text"
                        v-model="asset_product.serial_no"
                        class="form-control mb-2 mx-1"
                        :placeholder="$t('fixed_assets.serial_no')"
                      />
                    </div>
                     <div class="col-12 col-md-4">
                    <label for="asset_id">{{
                      $t("fixed_assets.alt_name")
                    }}</label>
                    <input
                      type="text"
                      v-model="asset_product.alt_name"
                      class="form-control mb-2 mx-1"
                      :placeholder="$t('fixed_assets.alt_name')"
                    />
                  </div>
                  <div class="col-12 col-md-4">
                    <label for="asset_id">{{
                      $t("fixed_assets.alt_name_en")
                    }}</label>
                    <input
                      type="text"
                      v-model="asset_product.alt_name_en"
                      class="form-control mb-2 mx-1"
                      :placeholder="$t('fixed_assets.alt_name_en')"
                    />
                  </div>
                    <div class="col-12 col-md-4">
                      <label for="asset_id">{{ $t("emps.branch") }}</label>
                      <select
                        class="form-select"
                        v-model="asset_product.branch_id"
                        @change="getBranchSites(asset_product.branch_id, index)"
                      >
                        <option
                          v-for="branch in company_branches"
                          :key="branch"
                          :value="branch.id"
                        >
                          {{
                            $i18n.locale == "en" ? branch.name_en : branch.name
                          }}
                        </option>
                      </select>
                    </div>
                    <div class="col-12 col-md-4">
                      <div class="">
                        <label for="asset_id">{{
                          $t("fixed_assets.branch_site")
                        }}</label>
                        <select
                          class="form-select"
                          v-model="asset_product.branch_site_id"
                        @change="getBranchSubSites(asset_product.branch_site_id, index)"

                        >
                          <option
                            v-for="site in asset_product.branch_sites"
                            :key="site"
                            :value="site.id"
                          >
                            {{
                              $i18n.locale == "en" ? site.name_en : site.name
                            }}
                          </option>
                        </select>
                      </div>
                    </div>
                      <div class="col-12 col-md-4">
                    <div class="">
                      <label for="asset_id">{{
                        $t("fixed_assets.branch_sub_site")
                      }}</label>
                      <select
                        class="form-select"
                        v-model="asset_product.branch_sub_site_id"
                      >
                        <option
                          v-for="site in asset_product.branch_sub_sites"
                          :key="site"
                          :value="site.id"
                        >
                          {{ $i18n.locale == "en" ? site.name_en : site.name }}
                        </option>
                      </select>
                    </div>
                  </div>
                    <div class="col-12 col-md-4">
                      <label for="asset_id">{{
                        $t("fixed_assets.initial")
                      }}</label>
                      <currency-input
                        required
                        v-model="asset_product.initial_book_value"
                        class="form-control mb-2 mx-1"
                        :placeholder="$t('fixed_assets.initial')"
                      />
                    </div>
                    <!-- <div class="col-12 col-md-4">
                    <label for="asset_id">{{
                      $t("fixed_assets.installation_date")
                    }}</label>
                    <input
                      required
                      v-model="asset_product.installation_date"
                      type="date"
                      class="form-control"
                    />
                  </div> -->
                    <template v-if="asset_product?.fixed_asset?.depreciable">
                      <div class="col-12 col-md-4">
                        <label for="asset_id">{{
                          $t("fixed_assets.salvage_value")
                        }}</label>
                        <currency-input
                          required
                          :max="asset_product.initial_book_value"
                          v-model="asset_product.salvage_value"
                          class="form-control mb-2 mx-1"
                          :placeholder="$t('fixed_assets.salvage_value')"
                        />
                      </div>

                      <div class="col-12 col-md-4">
                        <label for="asset_id">{{
                          $t("fixed_assets.useful_life_years")
                        }}</label>
                        <input
                          type="number"
                          required
                          v-model="asset_product.useful_life_years"
                          class="form-control mb-2 mx-1"
                          :placeholder="$t('fixed_assets.useful_life_years')"
                        />
                      </div>
                    </template>
                    <div class="col-12 col-md-4">
                      <label for="asset_id">{{
                        $t("fixed_assets.replacement_cost")
                      }}</label>
                      <currency-input
                        required
                        :max="asset_product.initial_book_value"
                        v-model="asset_product.replacement_cost"
                        class="form-control mb-2 mx-1"
                        :placeholder="$t('fixed_assets.replacement_cost')"
                      />
                    </div>
                    <div class="col-12 col-md-4  align-self-center">
                      <div class="from-check form-check-inline">
                        <input
                          type="checkbox"
                          v-model="asset_product.under_warranty"
                          :id="'under_warranty-' + index"
                          class="form-check-input"
                        />
                        <label
                          class="form-check-label"
                          :for="'under_warranty-' + index"
