                <button
                  type="submit"
                  :disabled="
                    !((purchase_type.code=='expenses' && addExpense.every((expense) => expense?.search?.code))||(purchase_type.code=='assets' && addExpense.every((expense) => expense?.fixed_asset?.id)) )
